const now = new Date().toISOString();
const seen = new Set();
const out = [];

for (const item of items) {
  const j = item.json;
  const mlId = String(j.ID || j.id || '').trim();

  // pula vazios e duplicados dentro do mesmo batch
  if (!mlId || seen.has(mlId)) continue;
  seen.add(mlId);

  const toNum = (v) => {
    if (v === '' || v === null || v === undefined) return null;
    const n = Number(String(v).replace(',', '.'));
    return Number.isFinite(n) ? n : null;
  };

  out.push({
    json: {
      productname:       j.productname ?? '',
      price:             toNum(j.price),
      pricediscountrate: toNum(j.pricediscountrate),
      shopname:          j.shopname ?? 'Mercado Livre',
      offerlink:         j.offerlink ?? '',
      imageUrl:          j.imageURL ?? j.imageUrl ?? '',
      sending:           false,
      commission_rate:   toNum(j.commission_rate) ?? 5,
      commission_value:  toNum(j.commission_value),
      sales:             toNum(j.sales) ?? 0,
      rating:            toNum(j.rating) ?? 0,
      sent_at:           j.sent_at || now,
      priceoriginal:     toNum(j.priceoriginal),
      createdAt:         j.createdAt || now,
      updatedAt:         j.updatedAt || now,
    }
  });
}

return out;

// ===== Helpers =====
function buildPaginatedUrl(baseUrl, page) {
  // /lista.mercadolivre.com.br usa offset (_Desde_N), 48 items por página
  if (baseUrl.includes('lista.mercadolivre.com.br')) {
    if (page <= 1) return baseUrl;
    const offset = (page - 1) * 48 + 1;
    // Insere _Desde_N antes de outros modificadores (_OrderId, _DiscountRange etc.)
    if (baseUrl.includes('_')) {
      return baseUrl.replace(/_([A-Z])/, `_Desde_${offset}_$1`);
    }
    return `${baseUrl}_Desde_${offset}`;
  }

  // /ofertas, /c/, busca normal — paginação via ?page=N
  if (page <= 1) return baseUrl;
  const sep = baseUrl.includes('?') ? '&' : '?';
  return `${baseUrl}${sep}page=${page}`;
}

// ===== Estado do LOOP de tentativas (retry pra atingir o piso de produtos) =====
// Cada vez que o workflow volta aqui (porque não atingiu o piso na tentativa anterior),
// avança um bloco de páginas novo, pra não repetir o que já foi varrido antes.
const staticData = $getWorkflowStaticData('global'); // 'global' = compartilhado entre TODOS os nodes (precisa ser visto pelo 'Acumular Resultados')
const tentativa = Number(staticData.tentativa || 0);
const pagesPerAttempt = Number((($items('CONFIG ML')?.[0]?.json?.ml_queries)
  ? (() => { try {
        const raw = $items('CONFIG ML')[0].json.ml_queries;
        return (typeof raw === 'string' ? JSON.parse(raw) : raw).settings?.pages;
      } catch(e) { return null; } })()
  : null) || 5);
const pageOffset = tentativa * pagesPerAttempt;

// ===== Config =====
// Lê SEMPRE do node CONFIG ML (não do input direto), pois este node também é
// alimentado pelo "IF - Precisa Mais?" nas voltas do loop, cujo input não traz a config.
const cfg = ($items('CONFIG ML')?.[0]?.json) ?? {};

const settings = (() => {
  const s = cfg.ml_queries;
  if (s !== null && typeof s === 'object' && !Array.isArray(s)) return s.settings || s;
  if (typeof s === 'string') {
    try { const p = JSON.parse(s); return p.settings || p; } catch (e) {}
  }
  return {};
})();

const pages = Math.max(1, Number(settings.pages || 5));

const excludeCategories = Array.isArray(settings.exclude_categories)
  ? settings.exclude_categories
  : [];

// ===== Categorias (múltiplas URLs) =====
// ml_categories é um array de objetos { nome, url }, configurado no node CONFIG ML.
// Mantém compatibilidade: se não houver ml_categories, cai de volta no ml_base_url antigo (1 categoria só).
let categories = [];
try {
  const raw = cfg.ml_categories;
  if (Array.isArray(raw)) {
    categories = raw;
  } else if (typeof raw === 'string' && raw.trim()) {
    categories = JSON.parse(raw);
  }
} catch (e) {
  categories = [];
}

if (!Array.isArray(categories) || categories.length === 0) {
  // Fallback: comportamento antigo, 1 categoria via ml_base_url
  const baseUrl = String(
    cfg.ml_base_url ||
    'https://lista.mercadolivre.com.br/perfumes_OrderId_PRICE*DESC_DiscountRange_30-100'
  ).trim();
  categories = [{ nome: String(cfg.ml_category_name || 'perfumes').trim(), url: baseUrl }];
}

// Filtra categorias sem URL válida (ex: placeholders não preenchidos)
categories = categories.filter(c => c && c.url && !/^COLE_AQUI/i.test(String(c.url).trim()));

// ===== Geração dos links em ROUND-ROBIN por categoria =====
// Ordem de saída: cat1_p1, cat2_p1, cat3_p1, ..., catN_p1, cat1_p2, cat2_p2, ...
// Assim o scraping já visita as categorias intercaladas, página por página.
const out = [];

try {
  for (let page = 1; page <= pages; page++) {
    const pageReal = page + pageOffset; // avança o bloco de páginas a cada tentativa do loop
    for (const cat of categories) {
      const baseUrl = String(cat.url).trim();
      const categoryName = String(cat.nome || 'categoria').trim();
      const link = buildPaginatedUrl(baseUrl, pageReal);

      out.push({
        json: {
          marketplace: 'mercadolivre',
          name: `${categoryName}_p${pageReal}`,
          categoria: categoryName,
          page: pageReal,
          tentativa,
          link,
          min_discount:        Number(settings.min_discount ?? 10),
          min_rating:          Number(settings.min_rating   ?? 4.0),
          free_shipping:       settings.free_shipping ?? true,
          sort:                settings.sort || 'discount_desc',
          exclude_categories:  excludeCategories,
          ml_affiliate_endpoint: cfg.ml_affiliate_endpoint,
          ml_affiliate_tag:      cfg.ml_affiliate_tag,
          ml_csrf_token:         cfg.ml_csrf_token,
          ml_cookie:             cfg.ml_cookie,
        },
      });
    }
  }
} catch (err) {
  // Não derruba o workflow se algo bizarro acontecer aqui
  out.push({
    json: {
      _error: true,
      _error_message: err?.message ?? String(err),
      _categories: categories,
    },
  });
}

return out;

const CONFIG_NODE = "CONFIG ML";
const cfg = ($items(CONFIG_NODE)?.[0]?.json) ?? {};

const SCORE_BASE          = Number(cfg.score_base           ?? 50);
const BONUS_HAS_IMAGE     = Number(cfg.bonus_has_image      ?? 10);
const BONUS_HAS_PRICE     = Number(cfg.bonus_has_price      ?? 10);
const BONUS_HAS_LINK      = Number(cfg.bonus_has_link       ?? 10);
const BONUS_HAS_BRAND     = Number(cfg.bonus_has_brand      ?? 8);
const BONUS_HAS_CATEGORY  = Number(cfg.bonus_has_category   ?? 6);
const BONUS_HAS_DISCOUNT  = Number(cfg.bonus_has_discount   ?? 8);
const PENALTY_CLICK_TRACK = Number(cfg.penalty_click_track  ?? 5);

// ---------- Helpers ----------
function normText(s) {
  return String(s ?? "")
    .toLowerCase()
    .normalize("NFD").replace(/[\u0300-\u036f]/g, "")
    .replace(/\s+/g, " ")
    .trim();
}
function getTitle(j) { return j.nome || j.title || j.name || j["Nomes Produtos"] || j["['Nomes Produtos']"] || ""; }
function getImg(j)   { return j.imagem || j.image || j.img || j["Imagem Produtos (src)"] || j["['Imagem Produtos (src)']"] || ""; }
function getPriceText(j) { return j.preco || j.price || j.valor || ""; }
function getLink(j)  { return j.link_compra || j.link || j.url || ""; }
function includesAny(text, arr) { for (const k of arr) if (text.includes(k)) return true; return false; }

// ---------- Categorização genérica ----------
const CATEGORY_RULES = [
  { key: "eletronicos",  label: "Eletrônicos",       words: ["notebook", "laptop", "tablet", "celular", "smartphone", "iphone", "samsung", "xiaomi", "fone", "headphone", "earbud", "bluetooth", "smartwatch", "smart tv", "tv ", "monitor", "teclado", "mouse", "webcam", "alexa", "echo", "kindle"] },
  { key: "moda",         label: "Moda & Calçados",   words: ["tenis", "tênis", "sapato", "sandalia", "sandália", "bota", "chinelo", "camisa", "camiseta", "blusa", "calca", "calça", "vestido", "jaqueta", "casaco", "bolsa", "mochila", "carteira", "oculos", "óculos"] },
  { key: "beleza",       label: "Beleza & Perfumaria", words: ["perfume", "eau de parfum", "eau de toilette", "edp", "edt", "colonia", "fragrancia", "batom", "maquiagem", "base ", "rimel", "shampoo", "condicionador", "creme", "hidratante", "protetor solar", "sabonete"] },
  { key: "casa",         label: "Casa & Decoração",  words: ["sofa", "sofá", "cadeira", "mesa", "cama", "colchao", "colchão", "guarda-roupa", "estante", "cortina", "tapete", "luminaria", "luminária", "panela", "frigideira", "talher", "prato"] },
  { key: "eletrodomesticos", label: "Eletrodomésticos", words: ["geladeira", "fogao", "fogão", "microondas", "lavadora", "secadora", "ar condicionado", "ventilador", "aspirador", "liquidificador", "batedeira", "cafeteira", "air fryer", "fritadeira"] },
  { key: "esporte",      label: "Esporte & Fitness", words: ["bicicleta", "bike", "esteira", "halter", "haltere", "anilha", "yoga", "academia", "suplemento", "whey", "creatina", "proteina", "patins", "skate"] },
  { key: "infantil",     label: "Bebês & Infantil",  words: ["bebe", "bebê", "fralda", "carrinho de bebe", "berço", "berco", "mamadeira", "brinquedo", "lego", "boneca", "carrinho hot wheels"] },
  { key: "ferramentas",  label: "Ferramentas",       words: ["furadeira", "parafusadeira", "serra", "lixadeira", "esmerilhadeira", "kit ferramenta", "chave de fenda", "martelo"] },
  { key: "automotivo",   label: "Automotivo",        words: ["pneu", "oleo motor", "óleo motor", "bateria automotiva", "som automotivo", "tapete carro", "capa banco"] },
  { key: "games",        label: "Games",             words: ["playstation", "ps5", "ps4", "xbox", "nintendo", "switch", "controle ps", "joystick", "jogo ps"] },
  { key: "livros",       label: "Livros & Papelaria", words: ["livro", "caderno", "caneta", "lapis", "lápis", "agenda", "estojo"] },
  { key: "pet",          label: "Pet Shop",          words: ["racao", "ração", "petisco", "coleira", "guia pet", "aquario", "aquário", "areia gato"] }
];

const BRAND_RULES = [
  { key: "samsung",   label: "Samsung",      words: ["samsung", "galaxy"] },
  { key: "apple",     label: "Apple",        words: ["apple", "iphone", "ipad", "macbook", "airpods"] },
  { key: "xiaomi",    label: "Xiaomi",       words: ["xiaomi", "redmi", "poco"] },
  { key: "motorola",  label: "Motorola",     words: ["motorola", "moto g", "moto e"] },
  { key: "lenovo",    label: "Lenovo",       words: ["lenovo", "ideapad", "thinkpad"] },
  { key: "dell",      label: "Dell",         words: ["dell", "inspiron", "vostro"] },
  { key: "lg",        label: "LG",           words: ["lg "] },
  { key: "sony",      label: "Sony",         words: ["sony", "playstation", "bravia"] },
  { key: "philips",   label: "Philips",      words: ["philips", "walita"] },
  { key: "electrolux",label: "Electrolux",   words: ["electrolux"] },
  { key: "brastemp",  label: "Brastemp",     words: ["brastemp"] },
  { key: "consul",    label: "Consul",       words: ["consul", "consul "] },
  { key: "jbl",       label: "JBL",          words: ["jbl"] },
  { key: "anker",     label: "Anker",        words: ["anker", "soundcore"] },
  { key: "nike",      label: "Nike",         words: ["nike", "air force", "air max"] },
  { key: "adidas",    label: "Adidas",       words: ["adidas"] },
  { key: "lacoste",   label: "Lacoste",      words: ["lacoste"] },
  { key: "puma",      label: "Puma",         words: ["puma"] },
  { key: "natura",    label: "Natura",       words: ["natura"] },
  { key: "boticario", label: "O Boticário",  words: ["boticario", "boticário"] },
  { key: "lattafa",   label: "Lattafa",      words: ["lattafa"] }
];

const EXCLUDE_KEYWORDS = [
  "adulto", "sex", "erotico", "erótico",
  "cigarro eletronico", "vape", "pod ",
  "replica", "réplica", "falsificad"
];

function pick(rules, title) {
  for (const r of rules) if (includesAny(title, r.words)) return { key: r.key, label: r.label };
  return null;
}

function extractDiscountPct(priceText) {
  const m = String(priceText).match(/(\d{1,2})\s*%\s*OFF/i);
  return m ? Number(m[1]) : null;
}

function scoreItem(j, title, category, brand, discount_pct) {
  let score = SCORE_BASE;
  if (title.length >= 20) score += 5;
  if (title.length >= 40) score += 5;
  if (getImg(j))      score += BONUS_HAS_IMAGE;
  if (getPriceText(j))score += BONUS_HAS_PRICE;
  if (getLink(j))     score += BONUS_HAS_LINK;
  if (category)       score += BONUS_HAS_CATEGORY;
  if (brand)          score += BONUS_HAS_BRAND;
  if (discount_pct && discount_pct >= 20) score += BONUS_HAS_DISCOUNT;
  if (discount_pct && discount_pct >= 40) score += 5;
  if (discount_pct && discount_pct >= 60) score += 5;
  if (normText(getLink(j)).includes("click1.mercadolivre.com.br/mclics")) score -= PENALTY_CLICK_TRACK;
  const valueWords = ["oferta", "promo", "desconto", "off", "original", "lacrado", "novo", "lançamento", "lancamento", "kit", "combo", "frete gratis"];
  for (const w of valueWords) if (title.includes(w)) score += 1;
  return score;
}

// ---------- Execução ----------
const items = $input.all();
const out = [];

for (const it of items) {
  try {
    const j = it.json ?? {};
    const titleRaw = getTitle(j);
    const title    = normText(titleRaw);
    if (!title) continue;
    if (includesAny(title, EXCLUDE_KEYWORDS)) continue;

    const category = pick(CATEGORY_RULES, title) || { key: "geral", label: "Geral" };
    const brand    = pick(BRAND_RULES, title);
    const discount_pct = extractDiscountPct(getPriceText(j));
    const score    = scoreItem(j, title, category, brand, discount_pct);

    // categoria_origem = categoria definida na URL/CONFIG ML (round-robin das 5 categorias).
    // categoria_detectada = classificação automática por palavra-chave no título (eletrônicos, moda, etc).
    // "categoria" segue sendo a categoria de ORIGEM, pra não quebrar o round-robin e os limites por categoria no Dedupe.
    const categoriaOrigem = j.categoria || category.key;

    out.push({
      json: {
        ...j,
        categoria:           categoriaOrigem,
        categoria_origem:    categoriaOrigem,
        categoria_detectada: category.key,
        categoria_label:     category.label,
        name_key:        category.key,
        marca:           brand?.key ?? null,
        marca_label:     brand?.label ?? null,
        discount_pct_preview: discount_pct,
        score,
        _heuristica: { title_raw: titleRaw, title_norm: title }
      }
    });
  } catch (err) {
    out.push({ json: { _error: true, _error_message: err?.message ?? String(err), _original: it.json ?? null } });
  }
}

return out;

const CONFIG_NODE = "CONFIG ML";
const cfg = ($items(CONFIG_NODE)?.[0]?.json) ?? {};

const MIN_TOTAL          = Number(cfg.min_total          ?? 30);
const MAX_TOTAL          = Number(cfg.max_total          ?? 40);
const MAX_ITENS_CATEGORIA = Number(cfg.max_itens_categoria ?? 10);
const MAX_ITENS_MARCA    = Number(cfg.max_itens_marca    ?? 5);
const MIN_COMMISSION_VALUE = Number(cfg.min_commission_value ?? 8);

// Pesos do ranking (ajustáveis no CONFIG ML)
const W_SALES      = Number(cfg.w_sales      ?? 0.5);  // peso de vendas
const W_COMMISSION = Number(cfg.w_commission ?? 0.4);  // peso de comissão
const W_DISCOUNT   = Number(cfg.w_discount   ?? 0.1);  // peso de desconto

// ---------- Helpers ----------
function normText(s) {
  return String(s ?? "")
    .toLowerCase()
    .normalize("NFD").replace(/[\u0300-\u036f]/g, "")
    .replace(/\s+/g, " ")
    .trim();
}
function getTitle(j) { return j.nome || j.title || j.name || j["Nomes Produtos"] || j["['Nomes Produtos']"] || ""; }
function getLink(j)  { return j.link_compra || j.link || j.url || ""; }
function num(v, def = 0) { const n = Number(v); return Number.isFinite(n) ? n : def; }

// Extrai vendas do título ou de campo dedicado ("+1mil vendidos", "500 vendidos", etc)
function getSales(j) {
  if (j.sales != null) return num(j.sales);
  if (j.vendas != null) return num(j.vendas);
  const t = normText(getTitle(j) + " " + (j.preco || ""));
  const m = t.match(/\+?\s*(\d+(?:\.\d+)?)\s*(mil|k)?\s*vendid/i);
  if (m) {
    let n = parseFloat(m[1].replace(",", "."));
    if (m[2]) n *= 1000;
    return Math.round(n);
  }
  return 0;
}

function getCommission(j) {
  // commission_rate em % (ex: 7 = 7%) | commission_value em R$
  return num(j.commission_rate ?? j.comissao_pct ?? 0);
}

function getCommissionValue(j) {
  // Nesse ponto do pipeline a comissão real ainda não existe (só depois da API de afiliado).
  // Mantido apenas para fins informativos no campo _dedupe (debug), retorna 0 se não houver dado.
  if (j.commission_value_estimado != null) return num(j.commission_value_estimado);
  if (j.commission_value != null) return num(j.commission_value);
  return 0;
}

function getDiscountPct(j) {
  return num(j.discount_pct ?? j.discount_pct_preview ?? 0);
}

function getCategoria(j) { return normText(j.categoria || j.category || "geral"); }
function getMarca(j)     { return normText(j.marca || j.brand || "sem_marca"); }

function getExactKey(j) {
  const title = normText(getTitle(j));
  const link  = normText(getLink(j)).split("?")[0].split("#")[0];
  return `${title}||${link}`;
}

// ---------- Score composto (normaliza vendas/comissão/desconto pra 0-100) ----------
function rankScore(j, maxSales, maxCommission) {
  const sales      = getSales(j);
  const commission = getCommission(j);
  const discount   = getDiscountPct(j);

  const salesNorm      = maxSales      > 0 ? (sales      / maxSales)      * 100 : 0;
  const commissionNorm = maxCommission > 0 ? (commission / maxCommission) * 100 : 0;
  const discountNorm   = Math.min(discount, 100);

  return (
    salesNorm      * W_SALES +
    commissionNorm * W_COMMISSION +
    discountNorm   * W_DISCOUNT
  );
}

// ---------- 1) Dedupe exato ----------
const inputItems = $input.all();
const bestByExact = new Map();

for (const it of inputItems) {
  const j = it.json ?? {};
  if (!getLink(j)) continue;
  const k = getExactKey(j);
  const prev = bestByExact.get(k);
  // Mantém o de maior venda em caso de duplicata
  if (!prev || getSales(j) > getSales(prev.json ?? {})) {
    bestByExact.set(k, it);
  }
}

const deduped = Array.from(bestByExact.values()).map(it => it.json ?? {});

// ---------- 2) Calcula máximos pra normalização ----------
// OBS: a comissão REAL só fica disponível depois da chamada de API de afiliado
// (mais adiante no pipeline). Aqui ainda não dá pra filtrar por comissão com segurança,
// já que a taxa varia por produto/vendedor. O corte de comissão mínima acontece
// no final do pipeline, no node "Filter Already Saved", com o valor real.
const maxSales      = Math.max(1, ...deduped.map(getSales));
const maxCommission = Math.max(1, ...deduped.map(getCommission));

// ---------- 3) Ordena por score composto desc ----------
const ranked = deduped
  .map(j => ({ j, _rank_score: rankScore(j, maxSales, maxCommission) }))
  .sort((a, b) => b._rank_score - a._rank_score);

// ---------- 4) Monta filas por categoria + round-robin, com limites de marca/categoria ----------
// Função reaproveitável: dado um limite de categoria e de marca, monta as filas e
// intercala (round-robin) entre as categorias, respeitando MAX_TOTAL.
function montarRoundRobin(maxItensCategoria, maxItensMarca) {
  const marcaCount = new Map();
  const filaPorCategoria = new Map(); // categoria -> array de items prontos (na ordem de score)

  for (const { j, _rank_score } of ranked) {
    const cat   = getCategoria(j);
    const marca = getMarca(j);

    const fila = filaPorCategoria.get(cat) ?? [];
    if (fila.length >= maxItensCategoria) continue;

    const mCount = marcaCount.get(marca) ?? 0;
    if (marca !== "sem_marca" && mCount >= maxItensMarca) continue;

    fila.push({
      json: {
        ...j,
        _rank_score: Math.round(_rank_score * 100) / 100,
        _dedupe: {
          sales:           getSales(j),
          commission_rate: getCommission(j),
          commission_value: getCommissionValue(j),
          discount_pct:    getDiscountPct(j),
          min_total:       MIN_TOTAL,
          max_total:       MAX_TOTAL,
          max_categoria:   maxItensCategoria,
          max_marca:       maxItensMarca,
          exact_key:       getExactKey(j),
        }
      }
    });

    filaPorCategoria.set(cat, fila);
    marcaCount.set(marca, mCount + 1);
  }

  // Round-robin: mantém a ordem de categorias como apareceram primeiro no ranking
  // (segue o round-robin de scraping definido em "Montar Links ML").
  const categoriasOrdenadas = Array.from(filaPorCategoria.keys());
  const out = [];
  let algumaFilaTemItem = true;

  while (algumaFilaTemItem && out.length < MAX_TOTAL) {
    algumaFilaTemItem = false;
    for (const cat of categoriasOrdenadas) {
      if (out.length >= MAX_TOTAL) break;
      const fila = filaPorCategoria.get(cat);
      if (fila && fila.length > 0) {
        out.push(fila.shift());
        algumaFilaTemItem = true;
      }
    }
  }

  return out;
}

// ---------- 5) Afrouxa os limites progressivamente até atingir MIN_TOTAL ----------
// Tenta primeiro com os limites normais (max_itens_categoria / max_itens_marca).
// Se não atingir o piso de MIN_TOTAL produtos, vai abrindo os limites em estágios,
// até atingir o piso ou esgotar todos os candidatos disponíveis (sempre respeitando MAX_TOTAL).
const estagios = [
  { categoria: MAX_ITENS_CATEGORIA,     marca: MAX_ITENS_MARCA     },
  { categoria: MAX_ITENS_CATEGORIA + 4, marca: MAX_ITENS_MARCA + 2 },
  { categoria: MAX_ITENS_CATEGORIA + 8, marca: MAX_ITENS_MARCA + 4 },
  { categoria: MAX_TOTAL,               marca: MAX_TOTAL           }, // sem limite efetivo
];

let out = [];
for (const estagio of estagios) {
  out = montarRoundRobin(estagio.categoria, estagio.marca);
  if (out.length >= MIN_TOTAL) break;
}

return out;

// O parse de URL/preço e o filtro de comissão mínima já foram feitos
// no node "Comissão Mínima" (antes do Dedupe). Este node agora só repassa
// os itens, garantindo que os campos esperados existam (idempotente).
const results = [];

for (const item of $input.all()) {
  const j = item.json;
  if (!j.link_compra) continue; // segurança, não deveria ocorrer

  results.push({
    json: {
      ...j,
      link_compra: j.link_compra,
      price_old: j.price_old ?? null,
      price: j.price ?? null,
      discount_pct: j.discount_pct ?? null,
    }
  });
}

return results;

// Parse "R$3.899R$3.6496% OFF10x R$364,90 sem juros"
function parsePreco(str) {
  if (!str) return { price: null, priceOriginal: null, discount: null };
  const s = String(str);

  // remove parte de parcelamento "10x R$..."
  const main = s.split(/\d+x\s*R\$/i)[0];

  // regex que reconhece formato BR: 3.899 ou 3.649,90 (NÃO engole o "6" de "6% OFF")
  const priceRe = /R\$\s*(\d{1,3}(?:\.\d{3})*(?:,\d{1,2})?)/g;
  const prices = [];
  let lastEnd = 0;
  let m;
  while ((m = priceRe.exec(main)) !== null) {
    const v = parseFloat(m[1].replace(/\./g, '').replace(',', '.'));
    if (!isNaN(v) && v > 0) prices.push(v);
    lastEnd = m.index + m[0].length;
  }

  // desconto = dígitos logo após o último preço, antes do "% OFF"
  const tail = main.slice(lastEnd);
  const discM = tail.match(/^\s*(\d{1,2})\s*%\s*OFF/i);
  const discount = discM ? parseInt(discM[1], 10) : null;

  let price = null, priceOriginal = null;
  if (prices.length >= 2) {
    priceOriginal = prices[0];
    price = prices[1];
  } else if (prices.length === 1) {
    price = prices[0];
    // se só tem 1 preço mas tem desconto, calcula o original
    if (discount && discount > 0 && discount < 100) {
      priceOriginal = Number((price / (1 - discount / 100)).toFixed(2));
    }
  }

  // se não veio desconto mas temos os 2 preços, calcula
  let finalDiscount = discount;
  if (!finalDiscount && price && priceOriginal && priceOriginal > price) {
    finalDiscount = Math.round((1 - price / priceOriginal) * 100);
  }

  return { price, priceOriginal, discount: finalDiscount };
}

function extractId(url) {
  if (!url) return '';
  // Cobre os formatos conhecidos de URL de produto do ML:
  //  - .../p/MLB123456            (página de produto com catálogo)
  //  - .../MLB-123456-nome...     (anúncio individual, com hífen)
  //  - .../MLB123456-nome...      (anúncio individual, sem hífen)
  //  - .../up/MLBU123456          (produto "universal"/catálogo, prefixo MLBU)
  const m =
    url.match(/\/p\/([A-Z]+U?\d+)/i) ||
    url.match(/\/up\/([A-Z]+U?\d+)/i) ||
    url.match(/(MLB-?U?\d+)/i);
  return m ? m[1].replace('-', '').toUpperCase() : '';
}

// A API de afiliado do ML (createLink) NÃO retorna a comissão real — ela só gera o link.
// A comissão de afiliado varia muito por categoria (de ~5% a ~24%, confirmado com dados
// reais de ganhos do usuário). Por isso usamos uma TABELA DE COMISSÃO ESTIMADA POR CATEGORIA
// (configurável em "CONFIG ML" -> commission_rate_by_category), em vez de uma taxa fixa.
// Se a API algum dia passar a retornar a comissão real, ela tem prioridade sobre a tabela.
function extractCommissionRateFromApi(urlObj) {
  if (!urlObj) return null;
  const candidatos = [
    urlObj.commission_rate,
    urlObj.commission_percentage,
    urlObj.commission,
    urlObj.percentage,
    urlObj?.commission_info?.percentage,
    urlObj?.commission_info?.rate,
  ];
  for (const c of candidatos) {
    const n = Number(c);
    if (Number.isFinite(n) && n > 0) return n;
  }
  return null;
}

function getCommissionRateTable(cfg) {
  const raw = cfg.commission_rate_by_category;
  try {
    if (raw && typeof raw === 'object') return raw;
    if (typeof raw === 'string' && raw.trim()) return JSON.parse(raw);
  } catch (e) {}
  return {};
}

const cfg = ($items('CONFIG ML')?.[0]?.json) ?? {};
const COMMISSION_TABLE = getCommissionRateTable(cfg);
const DEFAULT_RATE = Number(cfg.commission_rate ?? COMMISSION_TABLE._default ?? 10);

function getCommissionRateByCategory(categoria) {
  const key = String(categoria || '').toLowerCase().trim();
  const rate = COMMISSION_TABLE[key];
  return Number.isFinite(Number(rate)) ? Number(rate) : DEFAULT_RATE;
}

const now = new Date().toISOString();
const out = [];

for (const item of $input.all()) {
  const d = item.json || item;
  const { price, priceOriginal, discount } = parsePreco(d.preco_produtos);

  // Tenta extrair o ID da URL retornada pela API de afiliado primeiro;
  // se vier vazio (a API não traz origin_url sempre), cai pro link original do scraping.
  const id = extractId(d.urls?.[0]?.origin_url) || extractId(d.link_compra_original);
  const offerlink = d.urls?.[0]?.short_url || d.link_produtos_afiliado || '';

  // Prioridade: 1) comissão real da API (se algum dia existir), 2) tabela por categoria
  const commissionRate = extractCommissionRateFromApi(d.urls?.[0])
    ?? getCommissionRateByCategory(d.categoria_origem);
  const commissionValue = price ? Number((price * commissionRate / 100).toFixed(2)) : 0;

  out.push({
    ID: id,
    productname: d.nome_produtos || '',
    price: price,
    pricediscountrate: discount,
    shopname: 'Mercado Livre',
    offerlink: offerlink,
    imageURL: d.imagem_produtos || '',
    sending: '',
    commission_rate: commissionRate,
    commission_value: commissionValue,
    sales: 0,
    rating: '',
    sent_at: now,
    priceoriginal: priceOriginal,
    createdAt: now,
    updatedAt: now,
  });
}

return out;

// ===== Dedupe contra a planilha: ID exato + nome MUITO parecido =====
// Regras:
//  1) Se o ID (MLBxxxx) já existe na planilha -> descarta.
//  2) Se o nome do produto for QUASE IDÊNTICO a um nome já salvo -> descarta.
//     OBS: o campo "shopname" não traz o vendedor real (o scraping não captura isso
//     sem uma chamada de API extra), então NÃO comparamos por loja — só por título.
//     Por isso o limiar de similaridade é alto (85% por padrão): só corta quando é
//     praticamente o mesmo produto, evitando cortar produtos diferentes que só
//     compartilham termos genéricos de marketing (ex: "Led", "Bivolt", "Kit").
//  3) Aplica a mesma regra dentro da própria execução (não deixa repetir entre si).
//  4) Corta no teto FINAL de produtos (max_total_final, padrão 40).

const STOPWORDS = new Set([
  'de','da','do','das','dos','com','para','por','em','no','na','nos','nas',
  'um','uma','uns','umas','e','ou','a','o','as','os','novo','nova','original',
  'kit','unidade','unidades','und','pct','pc','peca','peça','pecas','peças'
]);

function normText(s) {
  return String(s ?? '')
    .toLowerCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function getTokens(title) {
  return normText(title)
    .split(' ')
    .filter(w => w.length >= 3 && !STOPWORDS.has(w));
}

function tokenSet(title) {
  return new Set(getTokens(title));
}

// Similaridade de Jaccard: |interseção| / |união|
function jaccardSimilarity(setA, setB) {
  if (setA.size === 0 || setB.size === 0) return 0;
  let intersection = 0;
  for (const t of setA) if (setB.has(t)) intersection++;
  const union = setA.size + setB.size - intersection;
  return union > 0 ? intersection / union : 0;
}

function getTitle(j) {
  return j.productname || j.nome_produtos || j.nome || j.title || '';
}

// Limiar de similaridade ajustável via CONFIG ML -> similarity_threshold.
// Padrão 0.85 = 85% das palavras-chave em comum (bem alto, só pega quase-idênticos).
const cfg = ($items('CONFIG ML')?.[0]?.json) ?? {};
const SIMILARITY_THRESHOLD = Number(cfg.similarity_threshold ?? 0.85);
const MAX = Number(cfg.max_total_final ?? cfg.max_total ?? 40);
const MIN_COMMISSION_VALUE = Number(cfg.min_commission_value ?? 5);

// ---------- 1) Carrega produtos já salvos na planilha (ID + nome) ----------
const existingRows = ($('Get Existing IDs').all() || []).map(r => r.json || {});

const existingIds = new Set(
  existingRows.map(j => String(j.ID || '').trim()).filter(Boolean)
);

// Pré-computa tokens dos produtos já salvos (sem agrupar por loja, já que não temos esse dado real)
const existingTokens = existingRows
  .map(j => ({ title: getTitle(j), tokens: tokenSet(getTitle(j)) }))
  .filter(c => c.tokens.size > 0);

function isDuplicateOfExisting(tokens) {
  for (const cand of existingTokens) {
    if (jaccardSimilarity(tokens, cand.tokens) >= SIMILARITY_THRESHOLD) return true;
  }
  return false;
}

// ---------- 2) Filtra os itens desta execução ----------
const out = [];
const seenIdsNow = new Set();
const seenTokensNow = []; // tokens dos itens já aceitos NESTA execução

for (const item of $input.all()) {
  const j = item.json || {};
  const id = String(j.ID || '').trim();
  const title = getTitle(j);

  if (!id || !title) continue;

  // 2.0) Checagem final de comissão mínima (segurança extra, caso o preço/comissão
  // tenha mudado entre o scraping e a chamada de afiliado)
  const commissionValue = Number(j.commission_value ?? 0);
  if (commissionValue < MIN_COMMISSION_VALUE) continue;

  // 2.1) Dedupe exato por ID (planilha + execução atual)
  if (existingIds.has(id)) continue;
  if (seenIdsNow.has(id)) continue;

  // 2.2) Dedupe por nome QUASE IDÊNTICO, contra a planilha
  const tokens = tokenSet(title);
  if (isDuplicateOfExisting(tokens)) continue;

  // 2.3) Dedupe por nome QUASE IDÊNTICO, dentro desta mesma execução
  const dupNow = seenTokensNow.some(cand => jaccardSimilarity(tokens, cand) >= SIMILARITY_THRESHOLD);
  if (dupNow) continue;

  seenIdsNow.add(id);
  seenTokensNow.push(tokens);

  out.push(item);
  if (out.length >= MAX) break;
}

return out;

// ===== PARSE de URL e PREÇO (sem filtro de comissão aqui) =====
// A taxa de comissão do Mercado Livre VARIA por produto/categoria/vendedor,
// então não dá pra estimar com segurança antes de chamar a API de afiliado.
// Por isso este node NÃO filtra mais por comissão — só limpa a URL e extrai o preço.
// O corte de comissão mínima acontece depois, no "Filter Already Saved",
// usando a comissão REAL (vinda da API/parse final em "Code in JavaScript2").

// ===== 1. LIMPA URL =====
function cleanMlUrl(u) {
  if (!u) return '';

  const urlParamMatch = u.match(/[?&]url=([^&]+)/i);
  if (urlParamMatch) {
    try { u = decodeURIComponent(urlParamMatch[1]); } catch(e) {}
  }

  const clickMatch = u.match(/click1\.mercadolivre\.com\.br\/mclics\/[^\/]+\/(https?:\/\/[^\s"]+)/i);
  if (clickMatch) {
    try { u = decodeURIComponent(clickMatch[1]); } catch(e) {}
  }

  if (/click1\.mercadolivre/i.test(u)) return '';

  u = u.split('#')[0].split('?')[0];
  return u;
}

// ===== 2. PARSE PREÇO =====
function parseMlPrice(str) {
  if (!str) return { price_old: null, price: null, discount_pct: null };

  let s = str
    .replace(/\d+\s*x\s*R\$\s*[\d\.,]+/gi, ' ')
    .replace(/no\s+Pix|sem\s+juros|\bou\b|\bem\b/gi, ' ');

  const tryParse = (cleaned) => {
    const matches = [...cleaned.matchAll(/R\$\s?([\d\.]+(?:,\d{1,2})?)/g)];
    return matches
      .map(m => Math.round(parseFloat(m[1].replace(/\./g, '').replace(',', '.'))))
      .filter(n => n >= 5)
      .sort((a, b) => b - a);
  };

  const candidates = [];
  for (const re of [/(\d{2})\s*%\s*OFF/i, /(\d)\s*%\s*OFF/i]) {
    const m = s.match(re);
    if (!m) continue;
    const pct = parseInt(m[1]);
    const precos = tryParse(s.replace(m[0], ' '));
    if (precos.length >= 2) {
      const realPct = Math.round((1 - precos[1] / precos[0]) * 100);
      const diff = Math.abs(realPct - pct);
      candidates.push({ price_old: precos[0], price: precos[1], discount_pct: pct, diff });
    } else if (precos.length === 1) {
      candidates.push({ price_old: precos[0], price: precos[0], discount_pct: pct, diff: 99 });
    }
  }

  if (candidates.length) {
    candidates.sort((a, b) => a.diff - b.diff);
    const best = candidates[0];
    return { price_old: best.price_old, price: best.price, discount_pct: best.discount_pct };
  }

  const precos = tryParse(s);
  return { price_old: precos[0] ?? null, price: precos[1] ?? precos[0] ?? null, discount_pct: null };
}

// ===== APLICA =====
const results = [];

for (const item of $input.all()) {
  const j = item.json;
  const link = cleanMlUrl(j.link_compra || j.link_produtos || '');

  if (!link) continue; // sem link não tem como gerar link de afiliado, descarta

  const prices = parseMlPrice(j.preco || j.preco_produtos || '');
  if (!prices.price) continue; // sem preço não dá pra seguir, descarta

  results.push({
    json: {
      ...j,
      link_compra: link,
      price_old: prices.price_old,
      price: prices.price,
      discount_pct: prices.discount_pct,
    }
  });
}

return results;

// ===== Acumula resultados entre tentativas do loop de retry =====
// Cada tentativa do loop traz só os itens NOVOS encontrados nessa rodada
// (já filtrados contra a planilha pelo "Filter Already Saved"). Aqui somamos
// com tudo que já foi aceito nas tentativas anteriores desta mesma execução,
// guardado no Static Data do workflow (sobrevive entre os "saltos" do loop).

const staticData = $getWorkflowStaticData('global'); // 'global' = compartilhado entre TODOS os nodes (precisa ser visto pelo 'Montar Links ML')
const cfg = ($items('CONFIG ML')?.[0]?.json) ?? {};
const MIN_TOTAL = Number(cfg.min_total_final ?? 30);
const MAX_TOTAL_FINAL = Number(cfg.max_total_final ?? 40);
const MAX_TENTATIVAS = Number(cfg.max_tentativas ?? 10);

// Itens acumulados de tentativas anteriores (vazio na primeira tentativa)
const acumulados = Array.isArray(staticData.acumulados) ? staticData.acumulados : [];
const idsJaAcumulados = new Set(acumulados.map(j => j.ID).filter(Boolean));

// Soma os itens novos desta tentativa, evitando duplicar ID dentro do acumulado
const novosItens = $input.all().map(item => item.json || {});
for (const j of novosItens) {
  const id = String(j.ID || '').trim();
  if (id && idsJaAcumulados.has(id)) continue;
  if (id) idsJaAcumulados.add(id);
  acumulados.push(j);
  if (acumulados.length >= MAX_TOTAL_FINAL) break; // já bateu o teto, não precisa mais
}

const tentativaAtual = Number(staticData.tentativa || 0);

// Persiste o estado pra próxima volta do loop (se houver)
staticData.acumulados = acumulados;
staticData.tentativa = tentativaAtual + 1;

const atingiuPiso = acumulados.length >= MIN_TOTAL;
const atingiuTeto = acumulados.length >= MAX_TOTAL_FINAL;
const esgotouTentativas = (tentativaAtual + 1) >= MAX_TENTATIVAS;

const precisaContinuar = !atingiuPiso && !atingiuTeto && !esgotouTentativas;

// Retorna UM item de controle (não os produtos) — o "IF - Precisa Mais?" decide
// com base em precisaContinuar. Os produtos acumulados ficam só no Static Data
// até a hora de finalizar (lidos pelo node "Finalizar Acumulado").
return [{
  json: {
    precisaContinuar,
    total_acumulado: acumulados.length,
    tentativa: tentativaAtual + 1,
    max_tentativas: MAX_TENTATIVAS,
    min_total: MIN_TOTAL,
    max_total_final: MAX_TOTAL_FINAL,
  }
}];

// ===== Lê os itens acumulados do Static Data e os entrega pro Salvar na Planilha =====
// Roda só quando o loop termina (atingiu piso, teto, ou esgotou tentativas).
const staticData = $getWorkflowStaticData('global');
const acumulados = Array.isArray(staticData.acumulados) ? staticData.acumulados : [];

// Limpa o estado pra próxima execução do workflow (schedule de 12h) começar do zero
staticData.acumulados = [];
staticData.tentativa = 0;

return acumulados.map(j => ({ json: j }));

// ===== Dedupe PRECOCE por ID (antes da chamada cara de API de afiliado) =====
// O link do produto (com o ID) já está disponível aqui, vindo direto do scraping HTML
// (não depende da API de afiliado). Comparando aqui, evitamos gastar uma chamada de API
// com produtos que já sabemos que existem na planilha — economia real de tempo/requisições.

function extractId(url) {
  if (!url) return '';
  const m =
    url.match(/\/p\/([A-Z]+U?\d+)/i) ||
    url.match(/\/up\/([A-Z]+U?\d+)/i) ||
    url.match(/(MLB-?U?\d+)/i);
  return m ? m[1].replace('-', '').toUpperCase() : '';
}

const existingIds = new Set(
  ($('Get Existing IDs').all() || [])
    .map(r => String(r.json.ID || '').trim())
    .filter(Boolean)
);

const out = [];
const seenIdsNow = new Set();

for (const item of $input.all()) {
  const j = item.json || {};
  const id = extractId(j.link_compra);

  // Sem ID extraível: deixa passar (a extração de ID mais robusta roda de novo depois
  // da API de afiliado, com fallback). Não descarta aqui pra não perder produto bom
  // só por um link num formato que essa extração simples não reconheceu.
  if (!id) {
    out.push(item);
    continue;
  }

  if (existingIds.has(id)) continue;       // já existe na planilha -> descarta, economiza API
  if (seenIdsNow.has(id)) continue;          // duplicado dentro desta mesma leva -> descarta
  seenIdsNow.add(id);

  out.push(item);
}

return out;
